#!/bin/sh
set -eu
g0=$("$EV" --session S1 --type gate.answered --body '{"step":"build","answer":"yes, build it"}')
bj=$("$EV" --session S1 --type job.dispatched --body '{"kind":"build","target":null,"tree":"repo","report":"reports/2.json","agent_type":"lab-builder","delivery":"cold","hot_agent":null,"slot":null,"replaces":null,"approval":'"$g0"',"payload":{"task":"write the scripts"},"act":{}}')
bja=$("$EV" --session S1 --type job.assigned --job "$bj" --agent ab1 --body '{"name":"build-ab1","tool_use_id":"tu-b1"}')
bs=$("$EV" --session S1 --type build.submitted --root self --job "$bj" --agent ab1 --body '{"commit":"c1","files":["a.sh","b.sh"],"report":"reports/'"$bj"'.json","answers":{},"declines":{}}')
gr=$("$EV" --session S1 --type gate.answered --root "$bs" --body '{"step":"review","answer":"yes, review it"}')
r1=$("$EV" --session S1 --type round.made --root "$bs" --body '{"kind":"code","targets":['"$bs"'],"base":"c0","head":"c1","slots":[{"slot":1,"kind":"shell","agent_type":"lab-reviewer","cover":["a.sh","b.sh"]}],"loop":null}')
v1=$("$EV" --session S1 --type job.dispatched --root "$bs" --round "$r1" --body '{"kind":"review","target":'"$r1"',"tree":"repo","report":"reports/7.json","agent_type":"lab-reviewer","delivery":"cold","hot_agent":null,"slot":1,"replaces":null,"approval":'"$gr"',"payload":{"cover":["a.sh","b.sh"],"diff":"c0..c1","earlier":[],"skipped":[]},"act":{}}')
v1a=$("$EV" --session S1 --type job.assigned --root "$bs" --round "$r1" --job "$v1" --agent ar1 --body '{"name":"review-shell-ar1","tool_use_id":"tu-v1"}')
"$EV" --session S1 --type review.submitted --root "$bs" --round "$r1" --job "$v1" --agent ar1 --body '{"report":"reports/'"$v1"'.json","findings":[{"kind":"shell","file":"a.sh","severity":"high","realism":"realistic","title":"unquoted variable"},{"kind":"shell","file":"b.sh","severity":"high","realism":"realistic","title":"missing set -u"}]}' >/dev/null
m1=$("$EV" --session S1 --type review.merged --root "$bs" --round "$r1" --body '{"findings":[{"id":"SHELL-01","kind":"shell","file":"a.sh","severity":"high","realism":"realistic","status":"open"},{"id":"SHELL-02","kind":"shell","file":"b.sh","severity":"high","realism":"realistic","status":"open"}],"verdict":"changes","targets":["SHELL-01","SHELL-02"],"gaps":[]}')
fc=$("$EV" --session S1 --type fix.chosen --root "$bs" --body '{"merge":'"$m1"',"query":{"severities":["high"]},"ids":["SHELL-01","SHELL-02"],"cap":3}')
fj=$("$EV" --session S1 --type job.dispatched --root "$bs" --body '{"kind":"fix","target":'"$m1"',"tree":"repo","report":"reports/12.json","agent_type":"lab-builder","delivery":"hot","hot_agent":"ab1","slot":null,"replaces":null,"approval":'"$fc"',"payload":{"findings":[{"id":"SHELL-01","kind":"shell","file":"a.sh","severity":"high","title":"unquoted variable"},{"id":"SHELL-02","kind":"shell","file":"b.sh","severity":"high","title":"missing set -u"}],"side":"production"},"act":{}}')
"$EV" --session S1 --type job.assigned --root "$bs" --job "$fj" --agent ab1 --body '{"name":"build-ab1","tool_use_id":"tu-f1"}' >/dev/null
fs=$("$EV" --session S1 --type build.submitted --root "$bs" --job "$fj" --agent ab1 --body '{"commit":"c2","files":["b.sh"],"report":"reports/'"$fj"'.json","answers":{"SHELL-01":"declined","SHELL-02":"done"},"declines":{"SHELL-01":"the variable never holds spaces"}}')
r2=$("$EV" --session S1 --type round.made --root "$bs" --body '{"kind":"code","targets":['"$fs"'],"base":"c1","head":"c2","slots":[{"slot":1,"kind":"shell","agent_type":"lab-reviewer","cover":["a.sh","b.sh"]}],"loop":'"$fc"'}')
v2=$("$EV" --session S1 --type job.dispatched --root "$bs" --round "$r2" --body '{"kind":"review","target":'"$r2"',"tree":"repo","report":"reports/16.json","agent_type":"lab-reviewer","delivery":"hot","hot_agent":"ar1","slot":1,"replaces":null,"approval":'"$fc"',"payload":{"cover":["a.sh","b.sh"],"diff":"c1..c2","earlier":[{"id":"SHELL-01","status":"open","title":"unquoted variable","answer":"declined","decline":"the variable never holds spaces"},{"id":"SHELL-02","status":"open","title":"missing set -u","answer":"done","decline":null}],"skipped":[]},"act":{}}')
"$EV" --session S1 --type job.assigned --root "$bs" --round "$r2" --job "$v2" --agent ar1 --body '{"name":"review-shell-ar1","tool_use_id":"tu-v2"}' >/dev/null
"$EV" --session S1 --type review.submitted --root "$bs" --round "$r2" --job "$v2" --agent ar1 --body '{"report":"reports/'"$v2"'.json","findings":[],"answers":{"SHELL-01":"insisted","SHELL-02":"open"}}' >/dev/null
m2=$("$EV" --session S1 --type review.merged --root "$bs" --round "$r2" --body '{"findings":[{"id":"SHELL-01","kind":"shell","file":"a.sh","severity":"high","realism":"realistic","status":"insisted"},{"id":"SHELL-02","kind":"shell","file":"b.sh","severity":"high","realism":"realistic","status":"open"}],"verdict":"changes","targets":["SHELL-01","SHELL-02"],"gaps":[]}')
fj2=$("$EV" --session S1 --type job.dispatched --root "$bs" --body '{"kind":"fix","target":'"$m2"',"tree":"repo","report":"reports/20.json","agent_type":"lab-builder","delivery":"hot","hot_agent":"ab1","slot":null,"replaces":null,"approval":'"$fc"',"payload":{"findings":[{"id":"SHELL-01","kind":"shell","file":"a.sh","severity":"high","title":"unquoted variable"},{"id":"SHELL-02","kind":"shell","file":"b.sh","severity":"high","title":"missing set -u"}],"side":"production"},"act":{}}')
"$EV" --session S1 --type job.assigned --root "$bs" --job "$fj2" --agent ab1 --body '{"name":"build-ab1","tool_use_id":"tu-f2"}' >/dev/null
fs2=$("$EV" --session S1 --type build.submitted --root "$bs" --job "$fj2" --agent ab1 --body '{"commit":null,"files":[],"report":"reports/'"$fj2"'.json","answers":{"SHELL-01":"declined","SHELL-02":"declined"},"declines":{"SHELL-01":"the variable never holds spaces","SHELL-02":"set -u breaks the optional arguments"}}')
